 279:     private static void writeWorkerJar(Path destination, String startClass)
 280:             throws IOException {
 281:         Manifest manifest = new Manifest();
 282:         Attributes attributes = manifest.getMainAttributes();
 283:         attributes.put(Attributes.Name.MANIFEST_VERSION, "1.0");
 284:         attributes.putValue("Start-Class", startClass);
 285:         try (JarOutputStream ignored = new JarOutputStream(
 286:                 java.nio.file.Files.newOutputStream(destination), manifest)) {
 287:             // The policy authenticates the executable manifest before any claim is exposed.
 288:         }
 289:     }
